#!/bin/sh
# Generated by AppKata for App. Do not edit — regenerated on update / settings change (req 17.4).
set -eu
id=io.appkata.app
rt="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
home=/home/kata/.local/share/appkata/sandboxes/app
info=/home/kata/.local/share/appkata/sandboxes/.identity/app
appdir=/home/kata/bin/apps/app/1.0
exe=bin/app
# Without a session runtime folder (no logind session: ssh without one, cron, a bare container)
# nothing below can work -- the proxy socket, the display sockets and the document view all live
# there -- so say which folder is missing rather than fail on the first mkdir.
mkdir -p "$home" "$rt/appkata" || { echo "AppKata: can't use the session's runtime folder $rt (XDG_RUNTIME_DIR); the sandbox needs a logged-in session." >&2; exit 1; }
# Where stderr goes (requirement 14.2). Started by AppKata's Open, it is already this app's log.
# Started from the app menu, a file manager or a shortcut -- the desktop entry passes the word
# --appkata-menu first -- there is no terminal, so nothing would show a refused launch: stderr is
# appended to that same log, rotated at 2 MB like AppKata's own, under a dated line. Started any
# other way (a command link in a terminal or a script) it stays the caller's, so a tool's `2>file`
# and pipelines keep meaning what they say. $logging tells the run-time line below.
log=/home/kata/.local/state/appkata/apps/app.log
logging=0
if [ /dev/fd/2 -ef "$log" ]; then
  logging=1
elif [ "${1:-}" = --appkata-menu ]; then
  shift
  mkdir -p "${log%/*}" 2>/dev/null || true
  if [ "$(stat -c %s "$log" 2>/dev/null || echo 0)" -gt 2097152 ]; then mv -f "$log" "${log%.log}-prev.log"; fi
  if printf -- '--- %s AppKata: starting %s (from the menu)\n' "$(date '+%Y-%m-%d %H:%M:%S')" App >> "$log" 2>/dev/null; then
    exec 2>>"$log"
    logging=1
  fi
fi
# bwrap is the sandbox. Without it the app can't run sandboxed, and AppKata never runs it any other
# way unasked (17.10; review 2, F16), so say so rather than leave the shell's "not found".
command -v bwrap >/dev/null 2>&1 || { printf "AppKata: bubblewrap (bwrap) isn't installed, so %s can't run sandboxed here. Install it, or set its sandbox to Off in AppKata (App Detail > Sandbox).\n" App >&2; exit 1; }
# A file or folder the app was given as an argument ("Open with", a drop on the menu entry, `tool
# ~/x.txt`, `--file=~/x.txt`) is a host path: one in a granted folder becomes the path the app sees it
# at, the rest are handed over through the document portal from the host side. Without python3-gi or
# a document portal the arguments pass through unchanged (requirement 17.6.2).
if [ $# -gt 0 ] && command -v python3 >/dev/null 2>&1; then
  if fwd=$(python3 /home/kata/.local/share/appkata/sandboxes/.identity/forward-files.py "$id" "$rt" ""  -- "$@" 2>/dev/null); then eval "set -- $fwd"; fi
fi
# The bwrap words decided at run time are prepended to "$@", ahead of the program and its own
# arguments, each word quoted -- so paths and values with spaces or glob characters stay whole.
set -- -- "$appdir/$exe" "$@"

guard() {
  case "$1" in "$HOME"/*) ;; *) return 0 ;; esac
  rel=${1#"$HOME"/}; p=$home
  while [ -n "$rel" ]; do
    case "$rel" in */*) seg=${rel%%/*}; rel=${rel#*/} ;; *) seg=$rel; rel= ;; esac
    [ -n "$seg" ] || continue
    p="$p/$seg"
    if [ -L "$p" ]; then
      echo "AppKata: removing a link the app left at $p (a mount point)." >&2
      rm -f "$p"
    fi
    [ -e "$p" ] || return 0
  done
}

sock="$rt/appkata/bus-a172cedcae47474b.$$"
rm -f "$sock"
# Read the host bus with a default so `set -u` can't abort the launcher when it is unset.
upstream="${DBUS_SESSION_BUS_ADDRESS:-}"
# Proxy in its own tmpfs-root bwrap, with $rt bound rw so its socket is visible to the
# launcher (the P1 gotcha, resolved — local-proxy-test-plan.md). It carries *no*
# /.flatpak-info: the portals judge the caller by the proxy's root, and xdg-desktop-portal
# 1.18+ refuses a marked caller that is not a running Flatpak (requirement 17.6.1), so the
# app is a host caller to them and the proxy allows only the portal interfaces safe for one.
# Its own pid namespace ends it with bwrap: killing bwrap kills the namespace's first
# process (bwrap's, which keeps --die-with-parent), and with it everything inside. The
# proxy's own death signal is not enough: the kernel clears it at an exec that changes
# the security domain, as entering Ubuntu 25.04+'s unpriv_bwrap does, and every launch
# there left its proxy running (review 2, F2; requirement 17.10.2).
bwrap --ro-bind /usr /usr --symlink usr/lib /lib --symlink usr/lib64 /lib64 \
  --symlink usr/bin /bin --ro-bind /etc /etc --proc /proc --dev /dev \
  --bind "$rt" "$rt" --unshare-pid --die-with-parent -- \
  xdg-dbus-proxy "$upstream" "$sock" --filter '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.OpenURI.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Settings.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Print.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Email.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.NetworkMonitor.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.ProxyResolver.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.MemoryMonitor.*@/org/freedesktop/portal/desktop' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Request.*@/org/freedesktop/portal/desktop/request/*' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Session.*@/org/freedesktop/portal/desktop/session/*' '--call=org.freedesktop.portal.Desktop=org.freedesktop.DBus.Introspectable.*@/org/freedesktop/portal/desktop' --broadcast=org.freedesktop.portal.Desktop=org.freedesktop.portal.Settings.SettingChanged@/org/freedesktop/portal/desktop --broadcast=org.freedesktop.portal.Desktop=org.freedesktop.portal.NetworkMonitor.changed@/org/freedesktop/portal/desktop --broadcast=org.freedesktop.portal.Desktop=org.freedesktop.portal.MemoryMonitor.LowMemoryWarning@/org/freedesktop/portal/desktop --talk=org.freedesktop.portal.IBus --talk=org.freedesktop.portal.Fcitx --own=io.appkata.app '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Inhibit.*@/org/freedesktop/portal/desktop' --talk=org.freedesktop.ScreenSaver '--own=org.mpris.MediaPlayer2.*' '--call=org.freedesktop.portal.Desktop=org.freedesktop.portal.Notification.*@/org/freedesktop/portal/desktop' --talk=org.freedesktop.Notifications --talk=org.freedesktop.secrets --own=org.freedesktop.secrets --talk=org.kde.StatusNotifierWatcher --own=org.kde.StatusNotifierItem-2-1 --own=org.kde.StatusNotifierItem-2-2 --own=org.kde.StatusNotifierItem-2-3 --own=org.kde.StatusNotifierItem-3-1 --own=org.kde.StatusNotifierItem-3-2 --own=org.kde.StatusNotifierItem-3-3 --own=org.kde.StatusNotifierItem-4-1 --own=org.kde.StatusNotifierItem-4-2 --own=org.kde.StatusNotifierItem-4-3 --own=org.kde.StatusNotifierItem-5-1 --own=org.kde.StatusNotifierItem-5-2 --own=org.kde.StatusNotifierItem-5-3 --own=org.kde.StatusNotifierItem-6-1 --own=org.kde.StatusNotifierItem-6-2 --own=org.kde.StatusNotifierItem-6-3 &
proxy=$!
# Wait for the socket, but stop early if the proxy died (e.g. no host bus) instead of
# blocking for the full timeout.
i=0; while [ ! -S "$sock" ] && kill -0 "$proxy" 2>/dev/null && [ "$i" -lt 50 ]; do i=$((i+1)); sleep 0.1; done
# Said plainly when it didn't start, rather than left to bwrap ("Can't find source path").
if [ ! -S "$sock" ]; then
  kill "$proxy" 2>/dev/null || true
  printf 'AppKata: the session-bus filter (xdg-dbus-proxy) did not start, so %s cannot run sandboxed here.\n' App >&2
  exit 1
fi

x11=0
if [ -n "${WAYLAND_DISPLAY:-}" ] && [ -e "$rt/$WAYLAND_DISPLAY" ]; then
  set -- --ro-bind "$rt/$WAYLAND_DISPLAY" "$rt/$WAYLAND_DISPLAY" --setenv WAYLAND_DISPLAY "$WAYLAND_DISPLAY" "$@"
  [ -n "${DISPLAY:-}" ] && x11=1
elif [ -n "${DISPLAY:-}" ]; then
  x11=1
fi
if [ "$x11" = 1 ]; then
  set -- --ro-bind-try /tmp/.X11-unix /tmp/.X11-unix --setenv DISPLAY "$DISPLAY" "$@"
  xa="${XAUTHORITY:-$HOME/.Xauthority}"
  if [ -e "$xa" ]; then guard "$xa"; set -- --ro-bind "$xa" "$xa" --setenv XAUTHORITY "$xa" "$@"; fi
fi

rc=$(readlink -f /etc/resolv.conf 2>/dev/null || true)
case "$rc" in
  /run/systemd/resolve/*) set -- --ro-bind /run/systemd/resolve /run/systemd/resolve "$@" ;;
  ""|/etc/*|/usr/*) ;;
  *) if [ -e "$rc" ]; then set -- --ro-bind "$rc" "$rc" "$@"; fi ;;
esac

for d in /usr/share/applications /usr/local/share/applications; do
  if [ -d "$d" ]; then set -- --tmpfs "$d" "$@"; fi
done

exported=$(export -p)
for v in LANG LANGUAGE LC_ALL LC_CTYPE LC_MESSAGES LC_NUMERIC LC_TIME TERM USER LOGNAME XDG_SESSION_TYPE XDG_CURRENT_DESKTOP DESKTOP_SESSION GTK_THEME QT_QPA_PLATFORMTHEME QT_STYLE_OVERRIDE XCURSOR_THEME XCURSOR_SIZE GDK_SCALE GDK_DPI_SCALE QT_SCALE_FACTOR LC_MONETARY LC_PAPER LC_MEASUREMENT LC_ADDRESS LC_TELEPHONE LC_NAME LC_COLLATE LC_IDENTIFICATION TZ QT_SCREEN_SCALE_FACTORS QT_AUTO_SCREEN_SCALE_FACTOR QT_ENABLE_HIGHDPI_SCALING GTK_IM_MODULE QT_IM_MODULE XMODIFIERS SDL_IM_MODULE http_proxy https_proxy ftp_proxy all_proxy no_proxy HTTP_PROXY HTTPS_PROXY FTP_PROXY ALL_PROXY NO_PROXY; do
  case "
$exported" in *"
export $v="*|*"
declare -x $v="*) ;; *) continue ;; esac
  eval "val=\$$v"
  set -- --setenv "$v" "$val" "$@"
done
for d in "$HOME/.themes" "$HOME/.icons" "$HOME/.fonts" "$HOME/.config/fontconfig" "$HOME/.local/share/fonts" "$HOME/.local/share/icons" "$HOME/.local/share/themes" "$appdir"; do guard "$d"; done

if [ "$logging" = 1 ]; then printf 'AppKata: running %s (%s)\n' "$appdir/$exe" "$(date +%s)" >&2; fi
status=0
exec 3< /home/kata/.local/share/appkata/sandboxes/.identity/seccomp-tty.bpf
bwrap \
  --ro-bind /usr /usr --symlink usr/lib /lib --symlink usr/lib64 /lib64 \
  --symlink usr/bin /bin --symlink usr/sbin /sbin --ro-bind /etc /etc \
  --ro-bind-try /var/cache/fontconfig /var/cache/fontconfig \
  --proc /proc --dev /dev --dev-bind-try /dev/dri /dev/dri --tmpfs /tmp --dir "$rt" \
  --bind-try "$rt/doc/by-app/$id" "$rt/doc" \
  --ro-bind-try /sys/block /sys/block --ro-bind-try /sys/bus /sys/bus --ro-bind-try /sys/class /sys/class \
  --ro-bind-try /sys/dev /sys/dev --ro-bind-try /sys/devices /sys/devices \
  --bind "$home" "$HOME" --ro-bind "$appdir" "$appdir" \
  --ro-bind-try "$HOME/.themes" "$HOME/.themes" --ro-bind-try "$HOME/.icons" "$HOME/.icons" \
  --ro-bind-try "$HOME/.fonts" "$HOME/.fonts" --ro-bind-try "$HOME/.config/fontconfig" "$HOME/.config/fontconfig" \
  --ro-bind-try "$HOME/.local/share/fonts" "$HOME/.local/share/fonts" \
  --ro-bind-try "$HOME/.local/share/icons" "$HOME/.local/share/icons" \
  --ro-bind-try "$HOME/.local/share/themes" "$HOME/.local/share/themes" \
  --ro-bind-try "$rt/pipewire-0" "$rt/pipewire-0" \
  --ro-bind-try "$rt/pulse/native" "$rt/pulse/native" \
  --ro-bind "$info" /.flatpak-info \
  --bind "$sock" "$rt/bus" \
  --ro-bind-try /home/kata/.local/share/appkata/sandboxes/.identity/bin /run/appkata \
  --unshare-all --share-net --die-with-parent --seccomp 3 \
  --clearenv --setenv HOME "$HOME" --setenv PATH /run/appkata:/usr/bin:/bin:/usr/sbin:/sbin \
  --setenv XDG_RUNTIME_DIR "$rt" \
  --setenv GDK_DEBUG no-portals \
  --setenv DBUS_SESSION_BUS_ADDRESS "unix:path=$rt/bus" \
  --chdir "$HOME" \
  "$@" || status=$?

kill "$proxy" 2>/dev/null || true
rm -f "$sock"
exit $status
